'use strict';

// MODULES //

import copysign from '@stdlib/math-base-special-copysign';
import { assign as sincos } from '@stdlib/math-base-special-sincos';
import isnan from '@stdlib/math-base-assert-is-nan';
import isInfinite from '@stdlib/math-base-assert-is-infinite';
import exp from '@stdlib/math-base-special-exp';
import PINF from '@stdlib/constants-float64-pinf';
import NINF from '@stdlib/constants-float64-ninf';


// VARIABLES //

var WORKSPACE = [ 0.0, 0.0 ];


// MAIN //

/**
* Evaluates the exponential function for a double-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* import Float64Array from '@stdlib/array-float64';
*
* var out = assign( 0.0, 0.0, new Float64Array( 2 ), 1, 0 );
* // returns <Float64Array>[ 1.0, 0.0 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var e;

	if ( isnan( re ) ) {
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = ( im === 0.0 ) ? im : NaN;
		return out;
	}
	if ( isInfinite( im ) ) {
		if ( re === PINF ) {
			out[ offsetOut ] = NINF;
			out[ offsetOut+strideOut ] = NaN;
			return out;
		}
		if ( re === NINF ) {
			out[ offsetOut ] = -0.0;
			out[ offsetOut+strideOut ] = copysign( 0.0, im );
			return out;
		}
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = NaN;
		return out;
	}
	e = exp( re );
	if ( im === 0.0 ) {
		out[ offsetOut ] = e;
		out[ offsetOut+strideOut ] = im;
		return out;
	}
	sincos( im, WORKSPACE, 1, 0 );
	out[ offsetOut ] = WORKSPACE[ 1 ] * e;
	out[ offsetOut+strideOut ] = WORKSPACE[ 0 ] * e;
	return out;
}


// EXPORTS //

export default assign;
